@prefix odrl: <http://www.w3.org/ns/odrl/2/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a odrl:Constraint ;
                    odrl:operator odrl:eq ;
                    odrl:rightOperand <http://publications.europa.eu/resource/authority/country/GBR> ] ;
            sh:resultMessage "An ODRL constraint must have exactly one odrl:leftOperand, given as an IRI (e.g. odrl:spatial)." ;
            sh:resultPath odrl:leftOperand ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:maxCount 1 ;
                    sh:message "An ODRL constraint must have exactly one odrl:leftOperand, given as an IRI (e.g. odrl:spatial)." ;
                    sh:minCount 1 ;
                    sh:nodeKind sh:IRI ;
                    sh:path odrl:leftOperand ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .
